import React, { useState, useEffect } from 'react';
import {
  Users, Globe, Smartphone, Monitor,
  TrendingUp, ChevronRight, Eye, MousePointer
} from 'lucide-react';

const TrafficChart = ({ timeRange }) => {
  const [activeDevice, setActiveDevice] = useState('all');
  const [trafficData, setTrafficData] = useState([]);

  useEffect(() => {
    // Données simulées
    const data = {
      sources: [
        { name: 'Direct', value: 35, color: 'from-blue-500 to-cyan-400' },
        { name: 'Réseaux sociaux', value: 28, color: 'from-purple-500 to-pink-400' },
        { name: 'Recherche', value: 22, color: 'from-emerald-500 to-teal-400' },
        { name: 'Référencement', value: 15, color: 'from-amber-500 to-orange-400' }
      ],
      devices: [
        { type: 'Mobile', value: 65, icon: <Smartphone className="h-4 w-4" />, change: '+12%' },
        { type: 'Desktop', value: 30, icon: <Monitor className="h-4 w-4" />, change: '+5%' },
        { type: 'Tablette', value: 5, icon: <Globe className="h-4 w-4" />, change: '-2%' }
      ],
      metrics: {
        sessions: 12542,
        bounceRate: 32.5,
        avgDuration: '4:32',
        conversion: 3.8
      }
    };
    setTrafficData(data);
  }, [timeRange]);

  const totalTraffic = trafficData.sources?.reduce((sum, source) => sum + source.value, 0) || 0;

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6 h-full">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-2">Trafic des utilisateurs</h3>
          <div className="flex items-center space-x-2">
            <div className="flex items-center text-green-500">
              <TrendingUp className="h-4 w-4 mr-1" />
              <span className="text-sm font-medium">Trafic en hausse</span>
            </div>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <button className="px-3 py-1.5 text-sm bg-neutral-100 dark:bg-neutral-800 rounded-xl text-neutral-700 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors">
            <Globe className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Metrics Grid */}
      <div className="grid grid-cols-2 gap-4 mb-6">
        <div className="col-span-2 grid grid-cols-2 gap-4">
          {trafficData.devices?.map((device, index) => (
            <div 
              key={index}
              className={`p-4 rounded-2xl transition-all duration-300 cursor-pointer hover:scale-105 ${
                activeDevice === device.type.toLowerCase()
                  ? 'bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/30 dark:to-primary-800/20 border-l-4 border-primary-500'
                  : 'bg-neutral-50 dark:bg-neutral-800/50'
              }`}
              onClick={() => setActiveDevice(device.type.toLowerCase())}
            >
              <div className="flex items-center justify-between mb-2">
                <div className="h-10 w-10 rounded-lg bg-primary-500/10 flex items-center justify-center">
                  {device.icon}
                </div>
                <span className={`text-xs font-medium px-2 py-1 rounded-full ${
                  device.change.startsWith('+') 
                    ? 'text-green-500 bg-green-500/10' 
                    : 'text-red-500 bg-red-500/10'
                }`}>
                  {device.change}
                </span>
              </div>
              <p className="text-2xl font-bold text-neutral-900 dark:text-white">{device.value}%</p>
              <p className="text-sm text-neutral-600 dark:text-neutral-400">{device.type}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Traffic Sources */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-4">
          <h4 className="font-semibold text-neutral-900 dark:text-white">Sources du trafic</h4>
          <span className="text-sm text-primary-600 dark:text-primary-400 flex items-center cursor-pointer hover:underline">
            Voir détails <ChevronRight className="h-4 w-4 ml-1" />
          </span>
        </div>

        <div className="space-y-4">
          {trafficData.sources?.map((source, index) => {
            const percentage = (source.value / totalTraffic) * 100;

            return (
              <div key={index} className="group">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center space-x-3">
                    <div className={`h-3 w-3 rounded-full bg-gradient-to-r ${source.color}`}></div>
                    <span className="text-sm font-medium text-neutral-900 dark:text-white">
                      {source.name}
                    </span>
                  </div>
                  <span className="text-sm font-bold text-neutral-900 dark:text-white">
                    {source.value}%
                  </span>
                </div>
                <div className="h-2 bg-neutral-200 dark:bg-neutral-800 rounded-full overflow-hidden">
                  <div 
                    className={`h-full rounded-full bg-gradient-to-r ${source.color} transition-all duration-1000 ease-out`}
                    style={{ width: `${percentage}%` }}
                  ></div>
                </div>
                <div className="text-right mt-1">
                  <span className="text-xs text-neutral-500 dark:text-neutral-500">
                    {Math.round(percentage)}% du total
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Stats en bas */}
      <div className="grid grid-cols-2 gap-4 pt-6 border-t border-neutral-200 dark:border-neutral-800">
        <div className="text-center p-3 rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100/30 dark:from-blue-900/10 dark:to-blue-800/5">
          <div className="h-10 w-10 rounded-lg bg-blue-500/10 flex items-center justify-center mx-auto mb-2">
            <Eye className="h-5 w-5 text-blue-500" />
          </div>
          <p className="text-xl font-bold text-neutral-900 dark:text-white">
            {trafficData.metrics?.sessions.toLocaleString()}
          </p>
          <p className="text-xs text-neutral-600 dark:text-neutral-400">Sessions</p>
        </div>

        <div className="text-center p-3 rounded-2xl bg-gradient-to-br from-emerald-50 to-emerald-100/30 dark:from-emerald-900/10 dark:to-emerald-800/5">
          <div className="h-10 w-10 rounded-lg bg-emerald-500/10 flex items-center justify-center mx-auto mb-2">
            <MousePointer className="h-5 w-5 text-emerald-500" />
          </div>
          <p className="text-xl font-bold text-neutral-900 dark:text-white">
            {trafficData.metrics?.conversion}%
          </p>
          <p className="text-xs text-neutral-600 dark:text-neutral-400">Conversion</p>
        </div>
      </div>
    </div>
  );
};

export default TrafficChart;
